// nexusComponent.js

export const useNexusComponent = () => {
  const state = {
    librosDestacados: [
      {
        id: 1,
        titulo: 'El Nombre del Viento',
        autor: 'Patrick Rothfuss',
        categoria: 'Fantasía',
        rating: 5,
        portada: 'https://imagessl4.casadellibro.com/a/l/t5/94/9788401352294.jpg'
      },
      {
        id: 2,
        titulo: 'Dune',
        autor: 'Frank Herbert',
        categoria: 'Ciencia Ficción',
        rating: 5,
        portada: 'https://imagessl5.casadellibro.com/a/l/t5/85/9788497596985.jpg'
      },
      {
        id: 3,
        titulo: '1984',
        autor: 'George Orwell',
        categoria: 'Distopía',
        rating: 5,
        portada: 'https://imagessl3.casadellibro.com/a/l/t5/63/9788499890963.jpg'
      },
      {
        id: 4,
        titulo: 'Cien años de soledad',
        autor: 'Gabriel García Márquez',
        categoria: 'Realismo Mágico',
        rating: 5,
        portada: 'https://imagessl0.casadellibro.com/a/l/t5/90/9788497592390.jpg'
      },
      {
        id: 5,
        titulo: 'Fahrenheit 451',
        autor: 'Ray Bradbury',
        categoria: 'Ciencia Ficción',
        rating: 4,
        portada: 'https://imagessl4.casadellibro.com/a/l/t5/94/9788466345194.jpg'
      }
    ],
    loading: false,
    error: null
  };

  const cargarLibrosDestacados = async () => {
    try {
      state.loading = true;
      state.error = null;
      // Simulamos una pequeña carga para mostrar el estado de loading
      await new Promise(resolve => setTimeout(resolve, 500));
      // No necesitamos cargar desde axios por ahora, usamos los datos estáticos
      console.log('Libros cargados:', state.librosDestacados.length);
    } catch (error) {
      console.error('Error al cargar los libros:', error);
      state.error = 'Error al cargar los libros destacados';
    } finally {
      state.loading = false;
    }
  };

  const setupScrollAnimations = () => {
    try {
      const io = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('animate-in');
            observer.unobserve(entry.target);
          }
        });
      }, { threshold: 0.12 });

      document.querySelectorAll('.scroll-animation').forEach(el => io.observe(el));
    } catch (e) {
      // Fallback: if IntersectionObserver not supported, reveal elements immediately
      document.querySelectorAll('.scroll-animation').forEach(el => el.classList.add('animate-in'));
    }
  };

  return {
    state,
    cargarLibrosDestacados,
    setupScrollAnimations
  };
};
